#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_mul_compact(
    a: *const KnowledgeCompact,
    b: *const KnowledgeCompact,
    result: *mut KnowledgeCompact,
) {
    if a.is_null() || b.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let a_val = (*a).value;
        let a_conf = (*a).confidence();
        let b_val = (*b).value;
        let b_conf = (*b).confidence();

        // Value: a * b
        (*result).value = a_val * b_val;

        // Confidence: geometric mean
        let combined_conf = (a_conf * b_conf).sqrt();
        (*result).quantized_conf = (combined_conf * 65535.0).clamp(0.0, 65535.0) as u16;

        // Provenance: XOR hash
        (*result).provenance_hash = (*a).provenance_hash ^ (*b).provenance_hash;
    }
}

/// Epistemic propagation: division (full layout)
/// Relative uncertainty propagation: same as multiplication
///
/// C signature: void sounio_epistemic_div_full(
///     const KnowledgeFull* a,
///     const KnowledgeFull* b,
///     KnowledgeFull* result
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_div_full(
    a: *const KnowledgeFull,
    b: *const KnowledgeFull,
    result: *mut KnowledgeFull,
) {
    if a.is_null() || b.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let a_val = (*a).value;
        let a_conf = (*a).confidence;
        let a_lower = (*a).conf_lower;
        let a_upper = (*a).conf_upper;
        let b_val = (*b).value;
        let b_conf = (*b).confidence;
        let b_lower = (*b).conf_lower;
        let b_upper = (*b).conf_upper;

        if b_val == 0.0 {
            (*result).value = f64::NAN;
            (*result).confidence = 0.0;
            (*result).conf_lower = f64::NAN;
            (*result).conf_upper = f64::NAN;
            (*result).provenance_id = (*a).provenance_id ^ (*b).provenance_id;
            (*result).timestamp = (*a).timestamp.max((*b).timestamp);
            (*result).revisable = (*a).revisable | (*b).revisable;
            return;
        }

        // Value: a / b
        let result_val = a_val / b_val;
        (*result).value = result_val;

        // Confidence: geometric mean
        (*result).confidence = (a_conf * b_conf).sqrt();

        // Relative uncertainty propagation
        let a_half_width = (a_upper - a_lower) / 2.0;
        let b_half_width = (b_upper - b_lower) / 2.0;

        let combined_half_width = if a_val == 0.0 {
            a_half_width / b_val.abs()
        } else {
            let rel_width_a = a_half_width / a_val.abs();
            let rel_width_b = b_half_width / b_val.abs();
            result_val.abs() * (rel_width_a * rel_width_a + rel_width_b * rel_width_b).sqrt()
        };

        (*result).conf_lower = result_val - combined_half_width;
        (*result).conf_upper = result_val + combined_half_width;

        // Provenance: combine IDs
        (*result).provenance_id = (*a).provenance_id ^ (*b).provenance_id;

        // Timestamp: most recent
        (*result).timestamp = (*a).timestamp.max((*b).timestamp);

        // Revisable if either input is revisable
        (*result).revisable = (*a).revisable | (*b).revisable;
    }
}

/// Epistemic propagation: division (compact layout)
///
/// C signature: void sounio_epistemic_div_compact(
///     const KnowledgeCompact* a,
///     const KnowledgeCompact* b,
///     KnowledgeCompact* result
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_div_compact(
    a: *const KnowledgeCompact,
    b: *const KnowledgeCompact,
    result: *mut KnowledgeCompact,
) {
    if a.is_null() || b.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let a_val = (*a).value;
        let a_conf = (*a).confidence();
        let b_val = (*b).value;
        let b_conf = (*b).confidence();

        if b_val == 0.0 {
            (*result).value = f64::NAN;
            (*result).quantized_conf = 0;
            (*result).provenance_hash = (*a).provenance_hash ^ (*b).provenance_hash;
            return;
        }

        // Value: a / b
        (*result).value = a_val / b_val;

        // Confidence: geometric mean
        let combined_conf = (a_conf * b_conf).sqrt();
        (*result).quantized_conf = (combined_conf * 65535.0).clamp(0.0, 65535.0) as u16;

        // Provenance: XOR hash
        (*result).provenance_hash = (*a).provenance_hash ^ (*b).provenance_hash;
    }
}

/// Epistemic meet operation: take minimum confidence
/// Used for skeptical combination (most conservative estimate)
///
/// C signature: void sounio_epistemic_meet(
///     const KnowledgeFull* a,
///     const KnowledgeFull* b,
///     KnowledgeFull* result
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_meet(
    a: *const KnowledgeFull,
    b: *const KnowledgeFull,
    result: *mut KnowledgeFull,
) {
    if a.is_null() || b.is_null() || result.is_null() {
        return;
    }

    unsafe {
        // Take value with lower confidence (more skeptical)
        if (*a).confidence < (*b).confidence {
            *result = *a;
        } else {
            *result = *b;
        }
    }
}

/// Epistemic join operation: weighted average by inverse variance
/// Used for credulous combination (averaging independent measurements)
///
/// C signature: void sounio_epistemic_join(
///     const KnowledgeFull* a,
///     const KnowledgeFull* b,
///     KnowledgeFull* result
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_join(
    a: *const KnowledgeFull,
    b: *const KnowledgeFull,
    result: *mut KnowledgeFull,
) {
    if a.is_null() || b.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let a_val = (*a).value;
        let a_conf = (*a).confidence;
        let a_lower = (*a).conf_lower;
        let a_upper = (*a).conf_upper;
        let b_val = (*b).value;
        let b_conf = (*b).confidence;
        let b_lower = (*b).conf_lower;
        let b_upper = (*b).conf_upper;

        // Use inverse-variance weighting
        // w_i = 1 / variance_i, where variance ≈ (width/2)²
        let a_half_width = (a_upper - a_lower) / 2.0;
        let b_half_width = (b_upper - b_lower) / 2.0;

        let a_variance = a_half_width * a_half_width;
        let b_variance = b_half_width * b_half_width;

        // Handle exact values (zero variance)
        if a_variance == 0.0 {
            *result = *a;
            return;
        }
        if b_variance == 0.0 {
            *result = *b;
            return;
        }

        let a_weight = 1.0 / a_variance;
        let b_weight = 1.0 / b_variance;
        let sum_weights = a_weight + b_weight;

        // Weighted average of values
        (*result).value = (a_weight * a_val + b_weight * b_val) / sum_weights;

        // Combined confidence: average weighted by inverse variance
        (*result).confidence = (a_weight * a_conf + b_weight * b_conf) / sum_weights;

        // Combined variance: 1 / (w_a + w_b)
        let combined_variance = 1.0 / sum_weights;
        let combined_half_width = combined_variance.sqrt();

        (*result).conf_lower = (*result).value - combined_half_width;
        (*result).conf_upper = (*result).value + combined_half_width;

        // Provenance: combine IDs
        (*result).provenance_id = (*a).provenance_id ^ (*b).provenance_id;

        // Timestamp: most recent
        (*result).timestamp = (*a).timestamp.max((*b).timestamp);

        // Revisable if either input is revisable
        (*result).revisable = (*a).revisable | (*b).revisable;
    }
}

/// Extract confidence value from Knowledge<T>
///
/// C signature: double sounio_epistemic_extract_confidence(
///     const KnowledgeFull* knowledge
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_epistemic_extract_confidence(
    knowledge: *const KnowledgeFull,
) -> f64 {
    if knowledge.is_null() {
        return 0.0;
    }

    unsafe { (*knowledge).confidence }
}
